const fs = require('fs');
const path = require('path');

const BASE_DIR = '/home/user/n8n-files/projects';

const input = $input.first().json;
const projectId = String(input.body?.project_id || input.project_id || '').replace(/[^a-zA-Z0-9_-]/g, '');
const subPath = String(input.body?.path || input.path || '').replace(/\.\./g, '').replace(/[^a-zA-Z0-9/_.-]/g, '_');
const fileName = String(input.body?.file || input.file || '').replace(/\.\./g, '').replace(/[\/]/g, '').replace(/[^a-zA-Z0-9._-]/g, '_');

if (!projectId || !subPath || !fileName) {
  throw new Error('project_id, path en file zijn verplicht.');
}

const filePath = path.join(BASE_DIR, projectId, subPath, fileName);

try {
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
    return [{ json: { success: true, message: `${fileName} verwijderd.` } }];
  } else {
    return [{ json: { success: false, message: 'Bestand niet gevonden.' } }];
  }
} catch (err) {
  throw new Error(`Fout bij verwijderen: ${err.message}`);
}
